<h1><?= e(__('Tạo tài khoản')) ?></h1><p class="text-muted mb-4"><?= e(__('Lưu chỗ ở yêu thích và quản lý chuyến đi ở một nơi.')) ?></p><form method="post" action="<?= e(url('/register')) ?>"><?= csrf_field() ?><?php if($returnTarget!==''): ?><input type="hidden" name="next" value="<?= e($returnTarget) ?>"><?php endif; ?><div class="form-group"><label for="full_name"><?= e(__('Họ và tên')) ?></label><input class="form-control" id="full_name" name="full_name" value="<?= e($old['full_name']??'') ?>" autocomplete="name" required></div><div class="form-group"><label for="email">Email</label><input class="form-control" id="email" autocomplete="email" type="email" name="email" value="<?= e($old['email']??'') ?>" required></div><div class="form-group"><label for="phone"><?= e(__('Số điện thoại')) ?></label><input class="form-control" id="phone" name="phone" value="<?= e($old['phone']??'') ?>" type="tel" autocomplete="tel"></div><div class="form-group"><label for="password"><?= e(__('Mật khẩu')) ?></label><input class="form-control" id="password" type="password" name="password" autocomplete="new-password" aria-describedby="password-rule" required><small class="form-text text-muted" id="password-rule"><?= e(__('Ít nhất 8 ký tự. Mật khẩu quá dài có thể bị từ chối, và chữ có dấu được tính nhiều hơn một ký tự.')) ?></small></div><button class="btn btn-primary btn-block" type="submit"><?= e(__('Tạo tài khoản')) ?></button></form><p class="text-center mt-4"><?= e(__('Đã có tài khoản?')) ?> <a href="<?= e(url('/login').($returnTarget!==''?'?next='.rawurlencode($returnTarget):'')) ?>"><?= e(__('Đăng nhập')) ?></a></p>

